def implyRightAnd (hq : 𝓢 ⊢ φ ➝ ψ) (hr : 𝓢 ⊢ φ ➝ χ) : 𝓢 ⊢ φ ➝ ψ ⋏ χ := by
  apply deduct';
  replace hq : [] ⊢[𝓢] φ ➝ ψ := of hq;
  replace hr : [] ⊢[𝓢] φ ➝ χ := of hr;
  exact and₃' (mdp' hq FiniteContext.id) (mdp' hr FiniteContext.id)

